#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
TOTAL_STAGES=9

# Helpers live below the template marker so the wizard library stays unchanged.
cpa_fail() { printf '\nCPA setup: %s\n' "$*" >&2; exit 1; }
cpa_default() {
  local key="$1" prompt="$2" fallback="$3"
  ask "$key" "$prompt [default: $fallback]"
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$fallback"
}
cpa_path() {
  local value="$1"
  [[ "$value" != '~' ]] || value="$HOME"
  [[ "$value" != '~/'* ]] || value="$HOME/${value:2}"
  [[ ! "$value" =~ [[:cntrl:]] ]] || cpa_fail 'Paths cannot contain control characters.'
  realpath -m -- "$value"
}
cpa_field() { python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))[sys.argv[2]])' "$1" "$2"; }
cpa_port() { [[ "$1" =~ ^[0-9]{1,5}$ ]] && (( 10#$1 >= 1024 && 10#$1 <= 65535 )); }

cpa_archive() {
  python3 - "$@" <<'CPA_ARCHIVE_PY'
import hashlib, json, os, platform, re, struct, sys, tarfile
from pathlib import Path

REQUIRED = {'cpa', 'launcher.cjs', 'headless.cjs', 'headless-update.cjs', 'environments.cjs',
            'runtime.cjs', 'harness-config.cjs', 'package.json', 'resources/cli-proxy-api',
            'resources/management.html', 'resources/ui-provenance.json',
            'node_modules/yaml/package.json', 'node_modules/smol-toml/package.json'}
ROOT_FILES = {name for name in REQUIRED if '/' not in name}
RESOURCES = {name for name in REQUIRED if name.startswith('resources/')}

def digest(file):
    value = hashlib.sha256()
    with open(file, 'rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            value.update(chunk)
    return value.hexdigest()

def root_path(value):
    raw = Path(value).expanduser().absolute()
    if raw.is_symlink():
        raise ValueError('Choose a regular folder, not a symbolic link.')
    root = raw.resolve()
    if root == Path('/') or root == Path.home().resolve() or len(root.parts) < 3:
        raise ValueError('Choose a dedicated CPA folder, such as ~/.local/opt/cpa.')
    return root

def target(root, name):
    parts = name.split('/')
    current = root
    for part in parts:
        current = current / part
        if current.is_symlink():
            raise ValueError('A package path contains a symbolic link: ' + str(current))
    if not current.resolve().is_relative_to(root):
        raise ValueError('A package path leaves its folder.')
    return current

def metadata(package, binary):
    if not isinstance(package, dict) or package.get('name') != 'cpa-headless' or not re.fullmatch(r'(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)', str(package.get('version', ''))):
        raise ValueError('This is not a CPA headless package.')
    machines = {'x86_64': ('x64', 62), 'aarch64': ('arm64', 183)}
    expected = machines.get(platform.machine())
    if not expected or len(binary) < 20 or binary[:4] != b'\x7fELF' or binary[4:6] != b'\x02\x01' or struct.unpack('<H', binary[18:20])[0] != expected[1]:
        raise ValueError('The bundled proxy does not match this VM CPU architecture.')
    return {'version': package['version'], 'arch': expected[0]}

def inspect(archive):
    archive = Path(archive)
    if not archive.is_file() or archive.stat().st_size > 192 * 1024 * 1024:
        raise ValueError('Choose a regular CPA .tar.gz archive smaller than 192 MiB.')
    entries, total, package, binary = {}, 0, None, None
    with tarfile.open(archive, 'r:gz') as tar:
        for member in tar:
            name = member.name.rstrip('/')
            if not name or not re.fullmatch(r'[a-zA-Z0-9@_./+ -]+', name) or any(part in ('', '.', '..') for part in name.split('/')) or name.startswith('/'):
                raise ValueError('Unsafe path in archive.')
            if member.isdir():
                continue
            allowed = name in ROOT_FILES or name in RESOURCES or name.startswith(('node_modules/yaml/', 'node_modules/smol-toml/'))
            total += member.size
            if not member.isfile() or member.issparse() or not allowed or name in entries or member.size < 0 or total > 512 * 1024 * 1024 or len(entries) >= 20000:
                raise ValueError('Unsupported, duplicate, or oversized archive entry: ' + name)
            value, count, captured = hashlib.sha256(), 0, bytearray()
            stream = tar.extractfile(member)
            for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                count += len(chunk)
                value.update(chunk)
                if name == 'package.json':
                    if count > 65536:
                        raise ValueError('Package metadata is too large.')
                    captured.extend(chunk)
                elif name == 'resources/cli-proxy-api' and not captured:
                    captured.extend(chunk[:64])
            if count != member.size:
                raise ValueError('Incomplete archive member.')
            if name == 'package.json':
                package = json.loads(captured)
            elif name == 'resources/cli-proxy-api':
                binary = bytes(captured)
            entries[name] = {'sha256': value.hexdigest(), 'bytes': count, 'mode': 0o755 if member.mode & 0o111 else 0o644}
    if not REQUIRED.issubset(entries):
        raise ValueError('The archive is missing required CPA files.')
    result = metadata(package, binary)
    result.update(sha256=digest(archive), files=len(entries), bytes=total)
    return result, entries

def matches(file, entry):
    return file.is_file() and not file.is_symlink() and file.stat().st_size == entry['bytes'] and digest(file) == entry['sha256']

def installed(directory):
    root = root_path(directory)
    for name in REQUIRED:
        if not target(root, name).is_file():
            raise ValueError('The installation is incomplete: ' + name)
    with (root / 'resources/cli-proxy-api').open('rb') as stream:
        binary = stream.read(64)
    return metadata(json.loads((root / 'package.json').read_text()), binary)

def install(archive, directory):
    result, entries = inspect(archive)
    root = root_path(directory)
    # Validate every existing file before making any change. Never overlay a different install.
    if root.exists() and not root.is_dir():
        raise ValueError('The installation path is not a directory.')
    for name, entry in entries.items():
        file = target(root, name)
        if file.exists() and not matches(file, entry):
            raise ValueError('An existing file differs from the archive. Choose an empty CPA folder: ' + str(file))
    if root.exists() and any(root.iterdir()) and not (root / 'package.json').exists():
        for file in root.rglob('*'):
            if file.is_symlink() or (file.is_file() and file.relative_to(root).as_posix() not in entries):
                raise ValueError('The destination contains unrelated files. Choose a dedicated CPA folder.')
    root.mkdir(parents=True, exist_ok=True)
    with tarfile.open(archive, 'r:gz') as tar:
        for member in tar:
            if member.isdir():
                continue
            file = target(root, member.name)
            if not file.exists():
                file.parent.mkdir(parents=True, exist_ok=True)
                with file.open('xb') as output, tar.extractfile(member) as stream:
                    for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                        output.write(chunk)
            file.chmod(entries[member.name]['mode'])
    installed(root)
    return result

def cleanup(archive, loose, installation, state, delete=False):
    info, entries = inspect(archive)
    raw = Path(loose).expanduser().absolute()
    if raw.is_symlink():
        raise ValueError('The loose-file folder must not be a symbolic link.')
    root, install_root, data_root = raw.resolve(), Path(installation).resolve(), Path(state).resolve()
    if root == Path('/') or root.is_relative_to(install_root) or root.is_relative_to(data_root):
        raise ValueError('Cleanup cannot target the installation, saved state, or filesystem root.')
    # These markers distinguish a flat CPA extraction from an unrelated project folder.
    for name in ('package.json', 'cpa', 'headless.cjs'):
        if not matches(target(root, name), entries[name]):
            raise ValueError('No complete matching flat CPA extraction was found in this folder. Nothing was removed.')
    candidates, kept, directories = [], [], set()
    for name, entry in entries.items():
        try:
            file, copy = target(root, name), target(install_root, name)
        except ValueError:
            kept.append(name)
            continue
        if file.is_relative_to(install_root) or file.is_relative_to(data_root):
            kept.append(name)
            continue
        if matches(file, entry) and matches(copy, entry):
            candidates.append({'path': str(file), 'bytes': entry['bytes']})
            if delete:
                file.unlink()
                directories.update(parent for parent in file.parents if parent != root and parent.is_relative_to(root))
        elif file.exists():
            kept.append(name)
    if delete:
        for directory in sorted(directories, key=lambda item: len(item.parts), reverse=True):
            try:
                directory.rmdir()  # Only remove empty directories. Never recursively delete.
            except OSError:
                pass
    return {'folder': str(root), 'files': candidates, 'kept': kept, 'bytes': sum(item['bytes'] for item in candidates), 'removed': delete}

def unit(install_dir, data_dir, node, name, user, import_file):
    def quote(value, command=False):
        if any(ord(character) < 32 or ord(character) == 127 for character in value):
            raise ValueError('Service values cannot contain control characters.')
        value = value.replace('\\', '\\\\').replace('"', '\\"').replace('%', '%%')
        if command:
            value = value.replace('$', '$$')
        return '"' + value + '"'
    if not re.fullmatch(r'[A-Za-z0-9_.-]+', user):
        raise ValueError('Unsupported service user name.')
    command = [node, str(Path(install_dir) / 'launcher.cjs'), 'serve', '--host', '0.0.0.0', '--port', os.environ['CPA_API_PORT'], '--name', name, '--data-dir', data_dir]
    if import_file and not (Path(data_dir) / 'config.yaml').exists():
        command += ['--import-config', import_file]
    return '\n'.join(['# CPA headless setup wizard', '[Unit]', 'Description=CPA headless environment',
        'After=network-online.target', 'Wants=network-online.target', '', '[Service]', 'Type=simple',
        'User=' + user, 'Environment=' + quote('HOME=' + str(Path.home())),
        'WorkingDirectory=' + install_dir.replace('%', '%%'), 'ExecStart=' + ' '.join(quote(value, True) for value in command),
        'Restart=on-failure', 'RestartSec=5', 'KillMode=mixed', 'UMask=0077', '', '[Install]', 'WantedBy=multi-user.target', ''])

try:
    action, *args = sys.argv[1:]
    if action == 'inspect':
        result = inspect(args[0])[0]
    elif action == 'installed':
        result = installed(args[0])
    elif action == 'install':
        result = install(*args)
    elif action in ('plan', 'clean'):
        result = cleanup(*args, delete=action == 'clean')
    elif action == 'verify-release':
        info, entries = inspect(args[0])
        release = json.loads(Path(args[1]).read_text())
        version = info['version']
        name = 'CPA-Headless-' + version + '-linux-' + info['arch'] + '.tar.gz'
        asset = next((value for value in release.get('assets', []) if value.get('name') == name), {})
        expected = 'https://github.com/NaveDanan/CPA-Desktop/releases/download/v' + version + '/' + name
        if release.get('tag_name') != 'v' + version or release.get('draft') or release.get('prerelease') or asset.get('digest') != 'sha256:' + info['sha256'] or asset.get('browser_download_url') != expected:
            raise ValueError('The archive does not match the published GitHub release digest.')
        result = info
    elif action == 'unit':
        print(unit(*args), end='')
        sys.exit(0)
    else:
        raise ValueError('Unknown archive helper action.')
    print(json.dumps(result))
except (ValueError, OSError, KeyError, StopIteration, tarfile.TarError) as error:
    print('CPA setup: ' + str(error), file=sys.stderr)
    sys.exit(1)
CPA_ARCHIVE_PY
}

cpa_health() {
  "$CPA_NODE_BIN" - "$CPA_DATA_DIR" "$CPA_API_PORT" "$CPA_PROXY_PORT" <<'CPA_HEALTH_JS'
const fs = require('node:fs');
const path = require('node:path');
(async () => {
  const [directory, port, proxy] = process.argv.slice(2);
  const identity = JSON.parse(fs.readFileSync(path.join(directory, 'environment-auth.json'), 'utf8'));
  const secrets = JSON.parse(fs.readFileSync(path.join(directory, 'desktop-secrets.json'), 'utf8'));
  const infoResponse = await fetch('http://127.0.0.1:' + port + '/api/environment/v1/info', { headers: { Authorization: 'Bearer ' + identity.token }, signal: AbortSignal.timeout(3000) });
  if (!infoResponse.ok) throw new Error('Connection API is not ready.');
  const info = await infoResponse.json();
  if (info.protocol !== 1 || info.id !== identity.id) throw new Error('The running service does not match this saved environment.');
  const proxyResponse = await fetch('http://127.0.0.1:' + proxy + '/v8/management/config', { headers: { Authorization: 'Bearer ' + secrets.managementKey }, signal: AbortSignal.timeout(3000) });
  if (!proxyResponse.ok) throw new Error('Proxy API is not ready.');
  await proxyResponse.arrayBuffer();
  console.log('CPA ' + info.version + ' is running. Both APIs accepted their saved credentials.');
})().catch(() => { process.exitCode = 1; });
CPA_HEALTH_JS
}

# Tests can source the functions without running any interactive setup stage.
if [[ "${BASH_SOURCE[0]}" != "$0" ]]; then return 0; fi
if [[ "${1:-}" == '--help' ]]; then
  printf '%s\n' 'Usage: bash setup-headless.sh [path/to/CPA-Headless-VERSION-linux-ARCH.tar.gz]' 'Run this wizard in an interactive Ubuntu SSH terminal as your normal VM user.' 'It installs CPA in its own folder, enables a boot service, reuses or generates its token, and guides PC connection.' 'Archive and loose-file cleanup each require confirmation after the running service passes its checks.'
  exit 0
fi
[[ -t 0 ]] || cpa_fail 'Download the script first, then run bash setup-headless.sh in your SSH terminal. Do not pipe it to bash.'
[[ "$EUID" -ne 0 ]] || cpa_fail 'Log in as your normal VM user, such as agent, then run the wizard. It will ask for sudo when needed.'
[[ "$(uname -s)" == 'Linux' ]] && grep -q '^ID=ubuntu$' /etc/os-release || cpa_fail 'This setup wizard is for Ubuntu VMs.'
command -v systemctl >/dev/null || cpa_fail 'This VM must use systemd.'
[[ -d /run/systemd/system ]] || cpa_fail 'This Ubuntu instance needs a running systemd service manager.'
command -v sudo >/dev/null || cpa_fail 'This setup requires sudo access for the Ubuntu service.'
umask 077
export TERM="${TERM:-xterm}"
[[ "$TERM" != dumb ]] || export TERM=xterm
ENV_FILE="${XDG_STATE_HOME:-$HOME/.local/state}/cpa-setup/settings.env"
[[ "$ENV_FILE" == /* ]] || ENV_FILE="$HOME/.local/state/cpa-setup/settings.env"
CPA_UNIT='/etc/systemd/system/cpa.service'
CPA_NODE_BIN=''
CPA_WORK=''
cpa_temp_cleanup() {
  if [[ -n "$CPA_WORK" && "$CPA_WORK" == /tmp/cpa-setup.* ]]; then
    rm -f -- "$CPA_WORK/node-setup.sh" "$CPA_WORK/archive.json" "$CPA_WORK/release.json" "$CPA_WORK/cpa.service" "$CPA_WORK/cleanup-plan.json"
    rmdir -- "$CPA_WORK" 2>/dev/null || true
  fi
}
trap cpa_temp_cleanup EXIT
trap 'printf "\nSetup did not finish. Fix the reported error, then run this wizard again.\n" >&2' ERR

banner 'CPA headless Ubuntu setup'

stage 'Choose the archive and folders'
say 'The VM runs CPA. Your PC connects to this environment.'
say 'Stages: settings, requirements, installation, boot service, health check,'
say 'token, cleanup, desktop connection, and provider sign-in.'
say 'Public setup choices are saved in a private settings file.'
say 'CPA stores its generated tokens in the selected data folder.'
confirm 'Use this setup flow?' || exit 0

CPA_ARCHIVE_CANDIDATE="${1:-}"
if [[ -z "$CPA_ARCHIVE_CANDIDATE" ]]; then
  shopt -s nullglob
  CPA_FOUND=( "$PWD"/CPA-Headless-*-linux-*.tar.gz "$HOME"/Downloads/CPA-Headless-*-linux-*.tar.gz )
  shopt -u nullglob
  [[ ${#CPA_FOUND[@]} -eq 0 ]] || CPA_ARCHIVE_CANDIDATE="${CPA_FOUND[0]}"
fi
cpa_default CPA_INSTALL_DIR 'Installation folder:' "$HOME/.local/opt/cpa"
cpa_default CPA_DATA_DIR 'Saved data and tokens folder:' "$HOME/.local/state/cpa"
cpa_default CPA_VM_NAME 'VM name in CPA:' "$(hostname)"
cpa_default CPA_ARCHIVE 'Downloaded .tar.gz path, or Enter to reuse an existing installation:' "$CPA_ARCHIVE_CANDIDATE"
cpa_default CPA_IMPORT_CONFIG 'Existing proxy config to import on first start, or Enter to skip:' ''
cpa_default CPA_API_PORT 'VM connection API port:' '8318'
CPA_INSTALL_DIR=$(cpa_path "$CPA_INSTALL_DIR")
CPA_DATA_DIR=$(cpa_path "$CPA_DATA_DIR")
[[ -z "$CPA_ARCHIVE" ]] || CPA_ARCHIVE=$(cpa_path "$CPA_ARCHIVE")
[[ -z "$CPA_IMPORT_CONFIG" ]] || CPA_IMPORT_CONFIG=$(cpa_path "$CPA_IMPORT_CONFIG")
[[ "$CPA_INSTALL_DIR" != "$HOME" && "$CPA_DATA_DIR" != "$HOME" && "$CPA_INSTALL_DIR" != '/' && "$CPA_DATA_DIR" != '/' ]] || cpa_fail 'Use dedicated installation and data folders.'
[[ "$CPA_INSTALL_DIR/" != "$CPA_DATA_DIR/"* && "$CPA_DATA_DIR/" != "$CPA_INSTALL_DIR/"* ]] || cpa_fail 'Keep the installation and data folders separate.'
[[ "$CPA_INSTALL_DIR" != /tmp/* && "$CPA_INSTALL_DIR" != /run/* && "$CPA_DATA_DIR" != /tmp/* && "$CPA_DATA_DIR" != /run/* ]] || cpa_fail 'Choose permanent folders rather than /tmp or /run.'
[[ -n "$CPA_VM_NAME" && ${#CPA_VM_NAME} -le 80 && ! "$CPA_VM_NAME" =~ [[:cntrl:]] ]] || cpa_fail 'Use a VM name of 1 to 80 characters.'
cpa_port "$CPA_API_PORT" || cpa_fail 'Use an API port from 1024 to 65535.'
CPA_API_PORT=$(( 10#$CPA_API_PORT ))
if [[ -f "$CPA_DATA_DIR/config.yaml" ]]; then CPA_IMPORT_CONFIG=''; fi
[[ -z "$CPA_IMPORT_CONFIG" || -f "$CPA_IMPORT_CONFIG" ]] || cpa_fail 'The import configuration file was not found.'
if [[ -n "$CPA_ARCHIVE" && ! -f "$CPA_ARCHIVE" ]]; then
  if [[ -f "$CPA_INSTALL_DIR/package.json" && -f "$CPA_INSTALL_DIR/launcher.cjs" ]]; then
    note 'The earlier archive is gone. The existing installation will be checked.'
    CPA_ARCHIVE=''
  else cpa_fail 'The archive was not found. Run the wizard from its folder, or enter its full path.'; fi
fi
[[ -n "$CPA_ARCHIVE" || -f "$CPA_INSTALL_DIR/package.json" ]] || cpa_fail 'Choose your downloaded .tar.gz archive.'
say "Install: $CPA_INSTALL_DIR"
say "Saved data: $CPA_DATA_DIR"
confirm 'Use these folders and preserve any existing CPA tokens?' || exit 0
mkdir -p -- "$(dirname "$ENV_FILE")"
write_env CPA_INSTALL_DIR "$CPA_INSTALL_DIR"
write_env CPA_DATA_DIR "$CPA_DATA_DIR"
write_env CPA_VM_NAME "$CPA_VM_NAME"
write_env CPA_ARCHIVE "$CPA_ARCHIVE"
write_env CPA_IMPORT_CONFIG "$CPA_IMPORT_CONFIG"
write_env CPA_API_PORT "$CPA_API_PORT"
export CPA_API_PORT

stage 'Check Ubuntu requirements and Node.js'
say 'CPA needs Node.js 22 or later. Ubuntu may ask for your sudo password.'
sudo -v
if ! command -v python3 >/dev/null || ! command -v curl >/dev/null; then
  confirm 'Install the missing Python/curl requirements with apt?' || cpa_fail 'Python 3 and curl are required.'
  sudo apt-get update
  sudo apt-get install -y python3 curl ca-certificates
fi
CPA_WORK=$(mktemp -d /tmp/cpa-setup.XXXXXXXX)
if ! command -v node >/dev/null || ! node -e 'process.exit(Number(process.versions.node.split(".")[0]) >= 22 ? 0 : 1)' 2>/dev/null; then
  say 'Node.js 22 will be installed from the NodeSource Ubuntu repository.'
  say 'Source: https://github.com/nodesource/distributions'
  confirm 'Configure NodeSource and install Node.js 22 with apt?' || cpa_fail 'Node.js 22 or later is required.'
  curl --fail --silent --show-error --location --proto '=https' --proto-redir '=https' https://deb.nodesource.com/setup_22.x -o "$CPA_WORK/node-setup.sh"
  sudo bash "$CPA_WORK/node-setup.sh"
  sudo apt-get install -y nodejs
  export PATH="/usr/bin:/bin:$PATH"
fi
CPA_NODE_BIN=$(cpa_path "$(type -P node)")
"$CPA_NODE_BIN" -e 'if (Number(process.versions.node.split(".")[0]) < 22) process.exit(1); console.log("Node.js " + process.versions.node + " is ready.")'
CPA_NODE_DIR=$(dirname "$CPA_NODE_BIN")
export PATH="$CPA_NODE_DIR:$PATH"
write_env CPA_NODE_BIN "$CPA_NODE_BIN"

stage 'Verify and install CPA in its own folder'
if [[ -n "$CPA_ARCHIVE" ]]; then
  cpa_archive inspect "$CPA_ARCHIVE" > "$CPA_WORK/archive.json"
  CPA_VERSION=$(cpa_field "$CPA_WORK/archive.json" version)
  CPA_ARCHIVE_SHA256=$(cpa_field "$CPA_WORK/archive.json" sha256)
  say "Checking the published SHA-256 for CPA $CPA_VERSION."
  curl --fail --silent --show-error --location --proto '=https' --proto-redir '=https' --max-time 60 "https://api.github.com/repos/NaveDanan/CPA-Desktop/releases/tags/v$CPA_VERSION" -o "$CPA_WORK/release.json"
  cpa_archive verify-release "$CPA_ARCHIVE" "$CPA_WORK/release.json" > /dev/null
  cpa_archive install "$CPA_ARCHIVE" "$CPA_INSTALL_DIR" > /dev/null
  write_env CPA_ARCHIVE_SHA256 "$CPA_ARCHIVE_SHA256"
else
  cpa_archive installed "$CPA_INSTALL_DIR" > "$CPA_WORK/archive.json"
  CPA_VERSION=$(cpa_field "$CPA_WORK/archive.json" version)
fi
write_env CPA_VERSION "$CPA_VERSION"
"$CPA_INSTALL_DIR/cpa" help > /dev/null
CPA_PROXY_PORT=$("$CPA_NODE_BIN" - "$CPA_INSTALL_DIR" "$CPA_DATA_DIR" "$CPA_IMPORT_CONFIG" <<'CPA_PORT_JS'
const fs = require('node:fs');
const path = require('node:path');
const [installation, directory, imported] = process.argv.slice(2);
const YAML = require(path.join(installation, 'node_modules/yaml'));
const saved = path.join(directory, 'config.yaml');
const source = fs.existsSync(saved) ? saved : imported;
const config = source ? YAML.parse(fs.readFileSync(source, 'utf8')) || {} : {};
const port = config.server?.port || config.port || 8317;
if (!Number.isInteger(port) || port < 1 || port > 65535) process.exit(1);
console.log(port);
CPA_PORT_JS
)
[[ "$CPA_API_PORT" -ne "$CPA_PROXY_PORT" ]] || cpa_fail 'The connection API port and proxy port must differ. Re-run and choose another connection port.'
write_env CPA_PROXY_PORT "$CPA_PROXY_PORT"
say "CPA $CPA_VERSION is installed in $CPA_INSTALL_DIR."
pause 'Press Enter to create the boot service.'

stage 'Create the Ubuntu boot service'
say "Service: $CPA_UNIT"
say "Runs as: $(id -un)"
say 'The service uses your selected data folder. It starts at boot without a desktop login.'
confirm 'Write the service and start or restart CPA?' || exit 0
if sudo test -L "$CPA_UNIT"; then cpa_fail 'The service file is a symbolic link. Inspect it before replacing it.'; fi
if sudo test -f "$CPA_UNIT"; then
  sudo grep -q '^Description=CPA headless environment$' "$CPA_UNIT" || cpa_fail 'An unrelated cpa.service already exists. It was not changed.'
  sudo cp -p -- "$CPA_UNIT" "$CPA_UNIT.backup-$(date -u +%Y%m%dT%H%M%SZ)-$$"
fi
if systemctl --user is-active --quiet cpa.service 2>/dev/null || systemctl --user is-enabled --quiet cpa.service 2>/dev/null; then
  systemctl --user show cpa.service --property=ExecStart --value | grep -Fq -- "$CPA_INSTALL_DIR" || cpa_fail 'A user service from a different folder exists. Stop it before continuing.'
  confirm 'Replace the existing user CPA service with this boot service?' || exit 0
  systemctl --user disable --now cpa.service
fi
mkdir -p -- "$CPA_DATA_DIR"
cpa_archive unit "$CPA_INSTALL_DIR" "$CPA_DATA_DIR" "$CPA_NODE_BIN" "$CPA_VM_NAME" "$(id -un)" "$CPA_IMPORT_CONFIG" > "$CPA_WORK/cpa.service"
sudo install -m 0644 -- "$CPA_WORK/cpa.service" "$CPA_UNIT"
sudo systemctl daemon-reload
write_env CPA_SERVICE cpa.service

stage 'Start CPA and check both APIs'
sudo systemctl enable cpa.service
sudo systemctl restart cpa.service
say 'Waiting for the proxy and connection API.'
CPA_READY=''
for (( CPA_ATTEMPT=0; CPA_ATTEMPT<30; CPA_ATTEMPT++ )); do
  if sudo systemctl is-active --quiet cpa.service && cpa_health > /dev/null 2>&1; then CPA_READY=yes; break; fi
  printf '.'
  sleep 1
done
printf '\n'
if [[ "$CPA_READY" != yes ]]; then
  say 'Read the error with: sudo journalctl -u cpa -n 50 --no-pager'
  cpa_fail 'CPA did not become ready. The archive and saved data were kept.'
fi
cpa_health
pause 'Press Enter to show the connection token.'

stage 'Generate or reuse the connection token'
say 'An existing token is reused. It is not rotated.'
say 'Connection token for CPA Desktop:'
"$CPA_INSTALL_DIR/cpa" token --data-dir "$CPA_DATA_DIR"
say 'Copy this token. You will paste it into CPA Desktop in stage 8.'
say 'CPA keeps it in environment-auth.json in your data folder.'
pause 'Press Enter when you have copied the token.'

stage 'Clean up the download and any earlier loose extraction'
if [[ -n "$CPA_ARCHIVE" && -f "$CPA_ARCHIVE" ]]; then
  say 'The running installation passed its checks.'
  say 'If an earlier tar command scattered CPA files, this step can remove matching copies.'
  if confirm 'Check a folder for loose files from this same CPA archive?'; then
    cpa_default CPA_LOOSE_DIR 'Folder that received the loose files:' "$(dirname "$CPA_ARCHIVE")"
    CPA_LOOSE_DIR=$(cpa_path "$CPA_LOOSE_DIR")
    if cpa_archive plan "$CPA_ARCHIVE" "$CPA_LOOSE_DIR" "$CPA_INSTALL_DIR" "$CPA_DATA_DIR" > "$CPA_WORK/cleanup-plan.json"; then
      CPA_CLEAN_COUNT=$(python3 -c 'import json,sys; print(len(json.load(open(sys.argv[1]))["files"]))' "$CPA_WORK/cleanup-plan.json")
      say "$CPA_CLEAN_COUNT matching CPA files can be removed from $CPA_LOOSE_DIR."
      say 'Only matching files are selected. Changed files, other files, and nonempty folders remain.'
      cp -- "$CPA_WORK/cleanup-plan.json" "$(dirname "$ENV_FILE")/last-cleanup-plan.json"
      say "Exact file list: $(dirname "$ENV_FILE")/last-cleanup-plan.json"
      if [[ "$CPA_CLEAN_COUNT" -gt 0 ]] && confirm 'Remove these verified loose CPA files?'; then
        cpa_archive clean "$CPA_ARCHIVE" "$CPA_LOOSE_DIR" "$CPA_INSTALL_DIR" "$CPA_DATA_DIR" > "$(dirname "$ENV_FILE")/last-cleanup-result.json"
        say 'Loose CPA files removed. The working installation and saved state were preserved.'
      fi
      write_env CPA_LOOSE_DIR "$CPA_LOOSE_DIR"
    else note 'Loose-file cleanup was skipped. No files were removed.'; fi
  fi
  say "Downloaded archive: $CPA_ARCHIVE"
  if confirm 'Delete this .tar.gz now that CPA is installed and running?'; then
    CPA_CURRENT_SHA256=$(sha256sum < "$CPA_ARCHIVE")
    CPA_CURRENT_SHA256=${CPA_CURRENT_SHA256%% *}
    [[ "$CPA_CURRENT_SHA256" == "$CPA_ARCHIVE_SHA256" ]] || cpa_fail 'The archive changed. It was not deleted.'
    rm -- "$CPA_ARCHIVE"
    CPA_ARCHIVE=''
    write_env CPA_ARCHIVE ''
    say 'The downloaded archive was removed.'
  fi
else note 'No downloaded archive was selected. Cleanup is not needed.'; fi
pause 'Press Enter for the PC connection steps.'

stage 'Connect this VM to CPA Desktop'
say 'CPA accepts direct connections on the VM connection port.'
say "Allow TCP port $CPA_API_PORT from your PC in the VM firewall or network rules."
say 'The proxy port stays private. The connection token controls remote access.'
cpa_default CPA_VM_ADDRESS 'VM IP address your PC can reach:' "$(hostname -I | awk '{print $1}')"
python3 -c 'import ipaddress,sys; ipaddress.ip_address(sys.argv[1])' "$CPA_VM_ADDRESS" || cpa_fail 'Enter the VM IPv4 or IPv6 address without a port.'
write_env CPA_VM_ADDRESS "$CPA_VM_ADDRESS"
CPA_CONNECTION_HOST="$CPA_VM_ADDRESS"
[[ "$CPA_CONNECTION_HOST" != *:* ]] || CPA_CONNECTION_HOST="[$CPA_CONNECTION_HOST]"
CPA_CONNECTION_URL="http://$CPA_CONNECTION_HOST:$CPA_API_PORT"
step 'On your PC, open CPA Desktop > CLI and Environments.'
say "Name: $CPA_VM_NAME"
say "Address: $CPA_CONNECTION_URL"
step 'Paste the connection token from stage 6, then click Connect.'
say 'Keep the sync option checked to copy your PC provider sign-ins and saved CLI models.'
say 'To display the token again on this VM:'
printf '  %q %q token --data-dir %q\n' "$CPA_NODE_BIN" "$CPA_INSTALL_DIR/launcher.cjs" "$CPA_DATA_DIR"
if confirm 'Did CPA Desktop connect to this VM?'; then write_env CPA_DESKTOP_CONNECTED yes; else
  write_env CPA_DESKTOP_CONNECTED no
  SKIPPED+=("Connect CPA Desktop to $CPA_CONNECTION_URL using the VM token.")
fi

stage 'Manage providers and models from your PC'
step 'Open CPA Desktop > CLI and Environments.'
step 'Next to this VM, click Models and providers to see its accounts and models.'
say 'To use the same accounts as your PC, set Sync from to This computer.'
step 'Select this VM, then click Sync providers to selected.'
say 'You can also use Connect provider in this VM detail area for a separate sign-in.'
step 'Choose local CLI models below and click Apply to CLIs.'
step 'Select the VM and click Sync models to selected, or use Sync both to all.'
say 'The page shows a separate result for each machine. Update older CPA versions first.'
if confirm 'Have you completed provider and model setup?'; then write_env CPA_PROVIDER_SETUP done; else
  write_env CPA_PROVIDER_SETUP pending
  SKIPPED+=("Finish providers and models in CPA Desktop > CLI and Environments.")
fi

finish
say 'The CPA service starts when the VM boots, even without a login.'
say 'Its token stays the same unless you rotate it or remove the saved state.'
say "Connect directly to $CPA_CONNECTION_URL. No SSH tunnel is needed."
say 'Service status: sudo systemctl status cpa --no-pager'
say 'Service logs: sudo journalctl -u cpa -n 50 --no-pager'
say 'Show the connection token again:'
printf '  %q %q token --data-dir %q\n' "$CPA_NODE_BIN" "$CPA_INSTALL_DIR/launcher.cjs" "$CPA_DATA_DIR"
